questionvariables.text:
Gval:rand_with_prohib(965,995,[977,980,981,983,991])/100;
Mval:rand_with_prohib(81,129,[83,89,97,100,101,103,107,109,113,127])*300;
Fval:Gval*Mval;

factList:[];
prime:2;
num:Mval;
while num>1 do (if primep(prime) and integerp(num/prime) then (factList:append(factList, [prime]), num:num/prime) else (prime:prime+1));

factList:random_permutation(factList);
LWlist:[pop(factList)*pop(factList),pop(factList)*pop(factList)];

Lval:max(first(LWlist),second(LWlist));
Lval:Lval/10^floor(log(Lval)/log(10));

Wval:min(first(LWlist),second(LWlist));
Wval:Wval/10^(floor(log(Wval)/log(10))+1);

Hval:pop(factList)*pop(factList);
Hval:Hval/10^(floor(log(Hval)/log(10))-1);

Pval:Fval/(Lval*Wval);
RHOval:Mval/(Lval*Wval*Hval);

feedbackvariables.text:
/* Node 1: Check correct answer */
/* Node 2: Worked solution */
/* Node 3: Incorrect unit conversion (answer out by a power of 10) (1) */
node3_test: if float(floor(decimalplaces(log(ans1/Pval)/log(10),8)))=float(decimalplaces(log(ans1/Pval)/log(10),8)) then 1 else 0;

/* Node 4: Solved using incorrect equation (P=FA or P=A/F) (1) */
node4_test: if significantfigures(ans1,3)=significantfigures((Fval/1000)*(Lval*Wval),3) or significantfigures(ans1,3)=significantfigures((Lval*Wval)/(Fval/1000),3) then 1 else 0;

/* Node 5: Combined node3 and node4 errors */
node5_test: if float(floor(decimalplaces(log(significantfigures(ans1,3)/significantfigures((Fval/1000)*(Lval*Wval),3))/log(10),8)))=float(decimalplaces(log(significantfigures(ans1,3)/significantfigures((Fval/1000)*(Lval*Wval),3))/log(10),8)) or float(floor(decimalplaces(log(significantfigures(ans1,3)/significantfigures((Lval*Wval)/(Fval/1000),3))/log(10),8)))=float(decimalplaces(log(significantfigures(ans1,3)/significantfigures((Lval*Wval)/(Fval/1000),3))/log(10),8)) then 1 else 0;

/* Node 1: Check correct answer */
/* Node 2: Worked solution */
/* Node 3: Incorrect unit conversion (answer out by a power of 10) (1) */
node3_test: if float(floor(decimalplaces(log(ans2/RHOval)/log(10),8)))=float(decimalplaces(log(ans2/RHOval)/log(10),8)) then 1 else 0;

/* Node 4: Solved using incorrect equation (p=m*V or P=V*m) (1) */
node4_test: if significantfigures(ans2,3)=significantfigures(Mval*(Lval*Wval*Hval),3) or significantfigures(ans2,3)=significantfigures((Lval*Wval*Hval)/Mval,3) then 1 else 0;

/* Node 5: Combined node3 and node4 errors */
node5_test: if float(floor(decimalplaces(log(significantfigures(ans2,3)/significantfigures(Mval*(Lval*Wval*Hval),3))/log(10),8)))=float(decimalplaces(log(significantfigures(ans2,3)/significantfigures(Mval*(Lval*Wval*Hval),3))/log(10),8)) or float(floor(decimalplaces(log(significantfigures(ans2,3)/significantfigures((Lval*Wval*Hval)/Mval,3))/log(10),8)))=float(decimalplaces(log(significantfigures(ans2,3)/significantfigures((Lval*Wval*Hval)/Mval,3))/log(10),8)) then 1 else 0;

/* Node 1: Check correct answer */
/* Node 2: Worked solution */
/* Node 3: If (a) or (b) incorrect, check for ecf (2) */
node3_test: if (notequal(float(ans1),float(Pval/1000)) or notequal(float(ans2),float(RHOval))) and (float(ans3)=float((ans1*1000)/(ans2*Hval))) then 1 else 0;

/* Node 4: Incorrect unit conversion of (a) (1) */
node4_test: if float(floor(decimalplaces(log(ans3*ans2*Hval/ans1)/log(10),8)))=float(decimalplaces(log(ans3*ans2*Hval/ans1)/log(10),8)) then 1 else 0;

/* Node 5: Incorrect rearranging of equation (g=Pph or g=ph/P) (1) */
node5_test: if significantfigures(ans3,3)=significantfigures(ans1*ans2*Hval,3) or significantfigures(ans3,3)=significantfigures((ans2*Hval)/ans1,3) then 1 else 0;

/* Node 6: Combined node4 and node5 errors */
node6_test: if float(floor(decimalplaces(log(significantfigures(ans3,3)/significantfigures(ans1*ans2*Hval,3))/log(10),8)))=float(decimalplaces(log(significantfigures(ans3,3)/significantfigures(ans1*ans2*Hval,3))/log(10),8)) or float(floor(decimalplaces(log(significantfigures(ans3,3)/significantfigures(ans2*Hval/ans1,3))/log(10),8)))=float(decimalplaces(log(significantfigures(ans3,3)/significantfigures(ans2*Hval/ans1,3))/log(10),8)) then 1 else 0;
